<?php
/**
 * Schmoll Modern: theme functions.
 * Page bodies come from import/content.json (generated by wp/build_wp.py in the site repository).
 */
if (!defined('ABSPATH')) exit;

define('SAP_VER', '{{VERSION}}');
define('SAP_LANGS', 'zh-hk|zh|ko|ms|th|vi');

/* ---------- setup ---------- */
add_action('after_setup_theme', function () {
    add_theme_support('title-tag');
    add_theme_support('post-thumbnails');
});
remove_action('wp_head', 'print_emoji_detection_script', 7);
remove_action('wp_print_styles', 'print_emoji_styles');
remove_action('wp_head', 'wp_generator');
remove_action('wp_head', 'wlwmanifest_link');
remove_action('wp_head', 'rsd_link');
remove_action('wp_enqueue_scripts', 'wp_enqueue_global_styles');
remove_action('wp_footer', 'wp_enqueue_global_styles', 1);
remove_action('wp_head', 'feed_links', 2);
remove_action('wp_head', 'feed_links_extra', 3);
remove_action('wp_head', 'wp_oembed_add_discovery_links');
add_filter('show_admin_bar', function ($show) { return current_user_can('edit_posts') ? $show : false; });

add_action('wp_enqueue_scripts', function () {
    foreach (array('wp-block-library', 'wp-block-library-theme', 'global-styles', 'classic-theme-styles') as $h) wp_dequeue_style($h);
    wp_enqueue_style('sap', get_theme_file_uri('assets/css/styles.css'), array(), SAP_VER);
    wp_enqueue_script('sap-i18n', get_theme_file_uri('assets/js/i18n.js'), array(), SAP_VER, true);
    wp_enqueue_script('sap-main', get_theme_file_uri('assets/js/main.js'), array('sap-i18n'), SAP_VER, true);
    wp_localize_script('sap-main', 'SAP', array('contact' => esc_url_raw(rest_url('sap/v1/contact'))));
}, 20);

/* ---------- per-page fields ---------- */
add_action('init', function () {
    foreach (array('page', 'post') as $type) {
        foreach (array('sap_seo_title', 'sap_desc', 'sap_head', 'sap_scripts', 'sap_noindex') as $key) {
            register_post_meta($type, $key, array('type' => 'string', 'single' => true, 'show_in_rest' => false,
                'auth_callback' => function () { return current_user_can('unfiltered_html'); }));
        }
    }
    register_post_type('sap_inquiry', array(
        'labels' => array('name' => 'Enquiries', 'singular_name' => 'Enquiry'),
        'public' => false, 'show_ui' => true, 'show_in_menu' => true, 'menu_icon' => 'dashicons-email-alt',
        'supports' => array('title', 'editor'), 'capability_type' => 'page', 'map_meta_cap' => true,
        'capabilities' => array('create_posts' => 'do_not_allow'),
    ));
});

function sap_meta($key) {
    return is_singular() ? (string) get_post_meta(get_queried_object_id(), $key, true) : '';
}

add_filter('pre_get_document_title', function ($title) {
    $t = sap_meta('sap_seo_title');
    return $t !== '' ? $t : $title;
});

add_action('wp_head', function () {
    $desc = sap_meta('sap_desc');
    $title = wp_get_document_title();
    if ($desc !== '') echo '<meta name="description" content="' . esc_attr($desc) . '">' . "\n";
    if (is_404() || sap_meta('sap_noindex') === '1') echo '<meta name="robots" content="noindex">' . "\n";
    if (is_singular()) {
        echo '<meta property="og:site_name" content="Schmoll Asia Pacific">' . "\n";
        echo '<meta property="og:title" content="' . esc_attr($title) . '">' . "\n";
        if ($desc !== '') echo '<meta property="og:description" content="' . esc_attr($desc) . '">' . "\n";
        echo '<meta property="og:url" content="' . esc_url(get_permalink()) . '">' . "\n";
        echo sap_meta('sap_head');
    }
}, 5);

// page-specific scripts go after the site scripts
add_action('wp_footer', function () { echo sap_meta('sap_scripts'); }, 30);

/* ---------- redirects: old addresses, language folders, old brochure files ---------- */
function sap_brochure_for($path) {
    $low = str_replace(array('-', '_'), '', strtolower($path));
    $map = array('eagle' => 'Eagle', 'hawk' => 'Hawk', 'falcon' => 'Falcon', 'raptor' => 'Raptor', 'combidrill' => 'CombiDrill', 'mdi' => 'MDI',
        'xra3' => 'XRA3', 'als' => 'Automation', 'automation' => 'Automation', 'fixture' => 'ProbeCard', 'probe' => 'ProbeCard', 'rmxy' => 'RMXY',
        'gtcpurchase' => 'GTC-Purchase', 'gtcservice' => 'GTC-Service', 'nda' => 'NDA');
    foreach ($map as $needle => $name) {
        if (strpos($low, $needle) !== false) {
            $file = in_array($name, array('GTC-Purchase', 'GTC-Service', 'NDA'), true) ? "Schmoll-Asia-Pacific-$name.pdf" : "Schmoll-$name-Brochure.pdf";
            $packs = array({{DOCMAP}});
            $n = isset($packs[$file]) ? $packs[$file] : 1;
            return content_url('plugins/schmoll-assets-' . $n . '/brochures/' . $file);
        }
    }
    return '';
}

function sap_target_for($path) {
    $path = trim($path, '/');
    if ($path === '') return '/';
    $map = (array) get_option('sap_redirects', array());
    if (isset($map[$path])) return $map[$path];
    $post = get_page_by_path($path, OBJECT, array('page', 'post'));
    if ($post && $post->post_status === 'publish') return wp_make_link_relative(get_permalink($post));
    return '';
}

add_action('template_redirect', function () {
    if (is_admin()) return;
    $path = trim((string) parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH), '/');

    // /zh/..., /ko/...: the site now switches language on the page itself
    if (preg_match('#^(' . SAP_LANGS . ')(?:/(.*))?$#', $path, $m)) {
        $target = sap_target_for(isset($m[2]) ? urldecode($m[2]) : '');
        if ($target === '') $target = '/';
        $parts = explode('#', $target, 2);
        $url = home_url($parts[0]) . '?lang=' . $m[1] . (isset($parts[1]) ? '#' . $parts[1] : '');
        wp_redirect($url, 302, 'Schmoll'); exit;
    }
    // brochure and legal PDFs that used to live in the media library
    if (preg_match('#^wp-content/uploads/.+\.pdf$#i', $path) && !file_exists(ABSPATH . $path)) {
        $pdf = sap_brochure_for($path);
        if ($pdf) { wp_redirect($pdf, 302, 'Schmoll'); exit; }
    }
    if (is_404()) {
        $map = (array) get_option('sap_redirects', array());
        if (isset($map[$path])) { wp_redirect(home_url($map[$path]), 301, 'Schmoll'); exit; }
    }
    // no archives: the Media page is the listing
    if (is_home() || is_archive() || is_search() || is_attachment() || is_feed()) { wp_redirect(home_url('/news/'), 302, 'Schmoll'); exit; }
}, 1);

/* ---------- contact form ---------- */
add_action('rest_api_init', function () {
    register_rest_route('sap/v1', '/contact', array(
        'methods' => 'POST', 'permission_callback' => '__return_true',
        'callback' => function (WP_REST_Request $req) {
            $d = (array) $req->get_json_params();
            if (!empty($d['website'])) return new WP_REST_Response(array('ok' => true), 200); // bots fill the hidden field
            $name = sanitize_text_field(isset($d['name']) ? $d['name'] : '');
            $email = sanitize_email(isset($d['email']) ? $d['email'] : '');
            $company = sanitize_text_field(isset($d['company']) ? $d['company'] : '');
            $message = sanitize_textarea_field(isset($d['message']) ? $d['message'] : '');
            $page = sanitize_text_field(isset($d['page']) ? $d['page'] : '');
            if ($name === '' || !is_email($email)) return new WP_Error('sap_invalid', 'Please enter your name and a valid email address.', array('status' => 400));
            if (isset($d['elapsed']) && (int) $d['elapsed'] < 2) return new WP_Error('sap_fast', 'Please try again.', array('status' => 400));
            if (strlen($name . $company . $message) > 6000) return new WP_Error('sap_long', 'Your message is too long.', array('status' => 400));
            $key = 'sap_rate_' . md5(isset($_SERVER['REMOTE_ADDR']) ? $_SERVER['REMOTE_ADDR'] : '');
            $count = (int) get_transient($key);
            if ($count >= 5) return new WP_Error('sap_rate', 'Too many messages. Please write to sales@schmoll-asia.com.', array('status' => 429));
            set_transient($key, $count + 1, HOUR_IN_SECONDS);

            $body = "Name: $name\nEmail: $email\nCompany: $company\nPage: $page\n\n$message";
            $id = wp_insert_post(array('post_type' => 'sap_inquiry', 'post_status' => 'private',
                'post_title' => wp_slash("$name" . ($company ? " ($company)" : '') . ' · ' . current_time('Y-m-d H:i')), 'post_content' => wp_slash($body)));
            $to = get_option('sap_contact_to', '');
            $sent = false;
            if ($to) $sent = wp_mail($to, 'Website enquiry: ' . $name . ($company ? " ($company)" : ''), $body, array('Reply-To: ' . $email));
            if ($id && !is_wp_error($id)) update_post_meta($id, 'sap_mailed', $sent ? '1' : '0');
            if ((!$id || is_wp_error($id)) && !$sent) return new WP_Error('sap_store', 'Your message could not be saved. Please write to sales@schmoll-asia.com.', array('status' => 500));
            return new WP_REST_Response(array('ok' => true), 200);
        },
    ));
    register_rest_route('sap/v1', '/import', array(
        'methods' => 'POST',
        'permission_callback' => function () { return current_user_can('manage_options'); },
        'callback' => function () { return new WP_REST_Response(sap_import(), 200); },
    ));
});

/* ---------- import: create or update every page and post from import/content.json ---------- */
function sap_import() {
    $file = get_theme_file_path('import/content.json');
    $data = json_decode((string) file_get_contents($file), true);
    if (!$data || empty($data['items'])) return array('error' => 'content.json missing or unreadable');
    kses_remove_filters(); // bodies contain inline SVG and scripts written by us
    $log = array(); $front = 0;
    foreach ($data['items'] as $it) {
        $type = $it['type'];
        $existing = get_posts(array('name' => $it['slug'], 'post_type' => $type, 'post_status' => 'any', 'numberposts' => 1));
        $post = array(
            'post_type' => $type, 'post_name' => $it['slug'], 'post_title' => wp_slash($it['title']), 'post_status' => 'publish',
            'post_content' => wp_slash("<!-- wp:html -->\n" . $it['content'] . "\n<!-- /wp:html -->"),
            'comment_status' => 'closed', 'ping_status' => 'closed',
        );
        if (!empty($it['date'])) { $post['post_date'] = str_replace('T', ' ', $it['date']); $post['post_date_gmt'] = get_gmt_from_date($post['post_date']); }
        if ($existing) { $post['ID'] = $existing[0]->ID; $id = wp_update_post($post, true); } else { $id = wp_insert_post($post, true); }
        if (is_wp_error($id)) { $log[] = $it['slug'] . ': ' . $id->get_error_message(); continue; }
        update_post_meta($id, 'sap_seo_title', wp_slash($it['seo_title']));
        update_post_meta($id, 'sap_desc', wp_slash($it['desc']));
        update_post_meta($id, 'sap_head', wp_slash($it['head']));
        update_post_meta($id, 'sap_scripts', wp_slash($it['scripts']));
        update_post_meta($id, 'sap_noindex', empty($it['noindex']) ? '0' : '1');
        if ($type === 'post' && !empty($it['category'])) {
            $term = term_exists($it['category'], 'category');
            if (!$term) $term = wp_insert_term(ucfirst($it['category']), 'category', array('slug' => $it['category']));
            if (!is_wp_error($term)) wp_set_post_terms($id, array((int) $term['term_id']), 'category');
        }
        if (!empty($it['front'])) $front = $id;
        $log[] = ($existing ? 'updated ' : 'created ') . $type . ' /' . $it['slug'];
    }
    kses_init();
    if ($front) { update_option('show_on_front', 'page'); update_option('page_on_front', $front); update_option('page_for_posts', 0); }
    update_option('sap_redirects', isset($data['redirects']) ? $data['redirects'] : array(), false);
    if (get_option('sap_contact_to', null) === null) add_option('sap_contact_to', 'sales@schmoll-asia.com');
    update_option('default_comment_status', 'closed'); update_option('default_ping_status', 'closed');
    foreach (array('hello-world' => 'post', 'sample-page' => 'page') as $slug => $type) {
        $old = get_posts(array('name' => $slug, 'post_type' => $type, 'post_status' => 'any', 'numberposts' => 1));
        if ($old) { wp_delete_post($old[0]->ID, true); $log[] = 'removed sample ' . $slug; }
    }
    global $wp_rewrite;
    if (get_option('permalink_structure') !== '/%postname%/') { $wp_rewrite->set_permalink_structure('/%postname%/'); }
    flush_rewrite_rules();
    update_option('sap_imported', $data['version'] . ' ' . current_time('mysql'), false);
    return array('version' => $data['version'], 'count' => count($data['items']), 'log' => $log);
}

add_action('admin_menu', function () {
    add_theme_page('Schmoll import', 'Schmoll import', 'manage_options', 'sap-import', function () {
        echo '<div class="wrap"><h1>Schmoll import</h1>';
        if (isset($_POST['sap_run']) && check_admin_referer('sap_import')) {
            $r = sap_import();
            echo '<div class="notice notice-success"><p>' . esc_html(isset($r['error']) ? $r['error'] : ('Imported ' . $r['count'] . ' items, version ' . $r['version'])) . '</p></div>';
            if (!empty($r['log'])) echo '<pre>' . esc_html(implode("\n", $r['log'])) . '</pre>';
        }
        echo '<p>Creates or updates all pages and posts from the content bundled with the theme. Pages edited by hand in WordPress are overwritten.</p>';
        echo '<p>Last import: ' . esc_html((string) get_option('sap_imported', 'never')) . '</p>';
        echo '<form method="post">'; wp_nonce_field('sap_import');
        echo '<p><button class="button button-primary" name="sap_run" value="1">Run import</button></p></form>';
        echo '<h2>Contact form</h2><p>Enquiries are stored under Enquiries and emailed to: <code>' . esc_html((string) get_option('sap_contact_to', '')) . '</code></p></div>';
    });
});
